using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class FixCableImportTransform {
 public static string Run(){var bike=UnityEngine.Object.FindFirstObjectByType<BicycleController>();var imported=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Models/bicycle/Optimized/Bicycle_Rigged.fbx");var source=imported.GetComponentsInChildren<MeshFilter>().First(f=>f.name=="RearControlCable");var model=bike.GetComponentsInChildren<MeshFilter>().First(f=>f.name=="Frame").transform.parent;var skin=bike.GetComponentInChildren<SkinnedMeshRenderer>();skin.transform.SetParent(model,false);skin.transform.localPosition=source.transform.localPosition;skin.transform.localRotation=source.transform.localRotation;skin.transform.localScale=source.transform.localScale;
 var mesh=skin.sharedMesh;var vertices=mesh.vertices;var weights=new BoneWeight[vertices.Length];for(int i=0;i<vertices.Length;i++){Vector3 point=bike.transform.InverseTransformPoint(skin.transform.TransformPoint(vertices[i]));float w=Mathf.SmoothStep(0,1,Mathf.InverseLerp(.27f,.41f,point.y));weights[i]=new BoneWeight{boneIndex0=0,weight0=1-w,boneIndex1=1,weight1=w};}
 mesh.boneWeights=weights;mesh.bindposes=new[]{bike.transform.worldToLocalMatrix*skin.transform.localToWorldMatrix,bike.steering.worldToLocalMatrix*skin.transform.localToWorldMatrix};var bounds=mesh.bounds;bounds.Expand(.005f);skin.localBounds=bounds;EditorUtility.SetDirty(mesh);EditorUtility.SetDirty(bike);EditorUtility.SetDirty(skin);AssetDatabase.SaveAssets();PrefabUtility.SaveAsPrefabAsset(bike.gameObject,"Assets/Models/bicycle/Optimized/Bicycle_Rideable.prefab");EditorSceneManager.SaveScene(bike.gameObject.scene);return "Cable import axis/scale retained, skin weights computed in bike space";}
}
